#include <stdio.h>
#include <stdlib.h>
struct Node { int value; struct Node *next; };

int main(void) {
    struct Node last = {9, NULL};
    struct Node middle = {6, &last};
    struct Node first = {3, &middle};
    struct Node *head = &first;
    struct Node *current = head;
    while (current != NULL) {
        printf("%d\n", current->value);
        current = current->next;
    }
    return 0;
}

#include <iostream>
struct Node { int value; Node* next; };

int main() {
    Node last{9, nullptr};
    Node middle{6, &last};
    Node first{3, &middle};
    Node* head = &first;
    Node* current = head;
    while (current != nullptr) {
        std::cout << current->value << '\n';
        current = current->next;
    }
    return 0;
}

